from jsonb_to_recordset($json$[{"id":"che-so-286","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Ethanol and water form a well-known","options":["minimum-boiling azeotrope","maximum-boiling azeotrope","ideal solution at all x","solid solution"],"answer_index":0,"explanation":"The ~95.6% ethanol azeotrope boils below the boiling points of both pure liquids.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"miscibility-azeotrope","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-287","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Aqueous hydrochloric acid forms a well-known","options":["maximum-boiling azeotrope","minimum-boiling azeotrope","gas–gas mixture only","colloid"],"answer_index":0,"explanation":"About 20.2% HCl boils higher than either pure water or pure HCl (negative deviation).","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"miscibility-azeotrope","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-288","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Fractional distillation cannot yield both pure components from","options":["an azeotropic mixture","an ideal benzene–toluene mix","a dilute urea solution","a gas–solid alloy"],"answer_index":0,"explanation":"At the azeotropic composition, liquid and vapour are identical, so further enrichment stops.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"miscibility-azeotrope","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-289","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"The ethanol–water azeotrope (about 95.6% ethanol) boils","options":["below the boiling point of either pure liquid","above both pure boiling points","at 100 °C only","at 0 °C"],"answer_index":0,"explanation":"It is a minimum-boiling (positive-deviation) azeotrope.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"miscibility-azeotrope","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-290","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"The HCl–water azeotrope (about 20.2% HCl) boils","options":["above 100 °C","below 50 °C","at the boiling point of pure HCl","at 0 °C"],"answer_index":0,"explanation":"Maximum-boiling azeotropes boil higher than either pure component; aqueous HCl azeotrope boils near 108.6 °C.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"miscibility-azeotrope","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-291","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Completely immiscible liquids such as water and chlorobenzene distill at a temperature","options":["lower than the boiling point of either pure liquid (steam distillation)","higher than both boiling points","equal to the arithmetic mean of the two boiling points","fixed by $K_H$ alone"],"answer_index":0,"explanation":"Each liquid exerts its own $p^\\circ$; the total reaches 1 atm below either normal boiling point.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"miscibility-azeotrope","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-292","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"A dilute aqueous HCl solution (weaker than the azeotrope) is fractionally distilled. Because the system has a maximum-boiling azeotrope, the first distillate is","options":["nearly pure water, while the residue approaches the azeotrope","nearly anhydrous HCl from the first drop","the 20% azeotrope from the start","ethanol"],"answer_index":0,"explanation":"On the water-rich side the more volatile vapour is almost pure water; the flask liquid moves toward the higher-boiling azeotrope.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"hard","concept_id":"miscibility-azeotrope","appear_count":0,"years":[],"exams":[],"verified":false}]$json$::jsonb) as x(
